   340  int av1_alloc_above_context_buffers(CommonContexts *above_contexts,
   341                                      int num_tile_rows, int num_mi_cols,
   342                                      int num_planes) {
   343    const int aligned_mi_cols =
   344        ALIGN_POWER_OF_TWO(num_mi_cols, MAX_MIB_SIZE_LOG2);
   345
   346    // Allocate above context buffers
   347    above_contexts->num_tile_rows = num_tile_rows;
   348    above_contexts->num_mi_cols = aligned_mi_cols;
   349    above_contexts->num_planes = num_planes;
   350    for (int plane_idx = 0; plane_idx < num_planes; plane_idx++) {
   351      above_contexts->entropy[plane_idx] = (ENTROPY_CONTEXT **)aom_calloc(
   352          num_tile_rows, sizeof(above_contexts->entropy[0]));
   353      if (!above_contexts->entropy[plane_idx]) return 1;
   354    }
   355
   356    above_contexts->partition = (PARTITION_CONTEXT **)aom_calloc(
   357        num_tile_rows, sizeof(above_contexts->partition));
   358    if (!above_contexts->partition) return 1;
   359
   360    above_contexts->txfm =
   361        (TXFM_CONTEXT **)aom_calloc(num_tile_rows, sizeof(above_contexts->txfm));
   362    if (!above_contexts->txfm) return 1;
   363
   364    for (int tile_row = 0; tile_row < num_tile_rows; tile_row++) {
   365      for (int plane_idx = 0; plane_idx < num_planes; plane_idx++) {
   366        above_contexts->entropy[plane_idx][tile_row] =
   367            (ENTROPY_CONTEXT *)aom_calloc(
   368                aligned_mi_cols, sizeof(*above_contexts->entropy[0][tile_row]));
   369        if (!above_contexts->entropy[plane_idx][tile_row]) return 1;
   370      }
   371
   372      above_contexts->partition[tile_row] = (PARTITION_CONTEXT *)aom_calloc(
   373          aligned_mi_cols, sizeof(*above_contexts->partition[tile_row]));
   374      if (!above_contexts->partition[tile_row]) return 1;
   375
   376      above_contexts->txfm[tile_row] = (TXFM_CONTEXT *)aom_calloc(
   377          aligned_mi_cols, sizeof(*above_contexts->txfm[tile_row]));
   378      if (!above_contexts->txfm[tile_row]) return 1;
   379    }
   380
   381    return 0;
   382  }
